  dsl: `workspace "Shop" "An online shop for buying products" {

    model {
        customer = person "Customer" "A customer who browses and purchases products"

        shop = softwareSystem "Shop" "An online shop for buying products" {
            webApp = container "Web App" "Serves the shop's pages to customers" "React" "Web"
            api = container "API" "Handles shop requests and business logic" "Node.js"
            database = container "Database" "Stores products, orders, and customers" "PostgreSQL" "Database"
        }

        customer -> webApp "Browses and purchases products" "HTTPS"
        webApp -> api "Makes requests" "HTTPS/JSON"
        api -> database "Reads and writes data" "SQL"
    }

    views {
        systemContext shop "SystemContext" {
            include *
            autoLayout
            title "System Context for Shop"
        }

        container shop "Containers" {
            include *
            autoLayout
            title "Containers for Shop"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}
`
});"}

